// Top-p (nucleus) renormalisation of dense row probabilities.
//
// For every row: c = max{v : S(v) >= p} with S(v) the float64 sum of the row
// entries >= v; output is x / S(c) for x >= c, else 0.
//
// One block per row, four phases separated by block barriers:
//   A  count + float64 sum histogram over the raw float bit pattern; a bin is
//      2"'^18 patterns wide (2.2% in value), which keeps shared-atomic pressure
//      low while still bracketing the cutoff tightly.
//   B  descending walk of that histogram -> bracket [lo, hi) holding c and
//      S(hi); loads a bit early, S(hi) < p <= S(lo).
//   C  9-bit descents inside the bracket: one row pass (global) then, when the
//      bracket fits in shared memory, pure shared-memory descents.
//   D  elementwise normalised write.
//
// Non-negative floats are ordered by their bit pattern, so every comparison in
// here is an unsigned integer compare of a pattern.

#include <torch/extension.h>
#include <c10/cuda/CUDAGuard.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_runtime.h>

#include <cstdint>
#include <mutex>

namespace {

constexpr int kThreads = 1024;
constexpr int kWarps = kThreads / 32;

constexpr int kShift = 18;                    // pattern bits dropped per bin
constexpr uint32_t kTopKey = 0x7F800000u;     // pattern of +inf
constexpr int kNumBins = int(kTopKey >> kShift) + 1;
constexpr int kBinsPerThread = (kNumBins + kThreads - 1) / kThreads;

constexpr int kRefineBits = 9;                // sub-bins per descent
constexpr int kMaxSub = 1 << kRefineBits;
constexpr int kGatherCap = 4096;              // elements kept in shared

// Level-1 walk publishes into ctl[0..1]; descend publishes into ctl[2..3].
constexpr int kCtlCross = 0;   // int  : crossing bin, -1 when the row never reaches p
constexpr int kCtlCount = 1;   // int  : elements seen inside the bracket
constexpr int kCtlSub = 2;     // int  : crossing sub-bin, -1 when absent
constexpr int kCtlPad = 3;
constexpr int kCtlSHi = 0;     // f64 : S(hi) of the bracket
constexpr int kCtlSLo = 1;     // f64 : S(lo) of the bracket

struct Shared {
  uint32_t cnt[kNumBins];
  double sum[kNumBins];
  uint32_t scnt[kMaxSub];
  double ssum[kMaxSub];
  uint32_t gathered[kGatherCap];
  double wsum[kWarps];
  double dctl[2];
  int ictl[4];
};

__device__ __forceinline__ uint32_t key_of(float x) {
  // Negatives, -0.0f and NaN collapse to the lowest key; they are dropped by
  // any non-negative cutoff, which is what the reference does as well.
  return (x >= 0.0f) ? (__float_as_uint(x) & 0x7FFFFFFFu) : 0u;
}

__device__ __forceinline__ uint32_t clamp_key(uint32_t k) {
  return k > kTopKey ? kTopKey : k;
}

// Exclusive suffix sum of `v` over the block, plus the caller'"'s own value.
__device__ __forceinline__ double block_suffix(double v, double* scratch) {
  constexpr unsigned kFull = 0xFFFFFFFFu;
  const int lane = threadIdx.x & 31;
  const int wid = threadIdx.x >> 5;
  double incl = v;
#pragma unroll
  for (int o = 1; o < 32; o <<= 1) {
    const double t = __shfl_down_sync(kFull, incl, o);
    if (lane + o < 32) incl += t;
  }
  if (lane == 0) scratch[wid] = incl;
  __syncthreads();
  double base = 0.0;
  if (lane == 0) {
    for (int i = wid + 1; i < kWarps; ++i) base += scratch[i];
  }
  base = __shfl_sync(kFull, base, 0);
  return base + (incl - v);
}

// Locate the sub-bin holding the cutoff and publish S(hi') / S(lo').
__device__ __forceinline__ void sub_walk(int nsub, double s_hi, double p, Shared& sh) {
  const int t = threadIdx.x;
  const double s = (t < nsub) ? sh.ssum[t] : 0.0;
  const double above = block_suffix(s, sh.wsum);
  if (t < nsub) {
    // above == S(lo_t) - s_t; the crossing is the only bin with both
    // S(hi_t) < p and S(lo_t) >= p.
    const double lo_sum = s_hi + above;
    if (lo_sum - s < p && lo_sum >= p) {
      sh.ictl[kCtlSub] = t;
      sh.dctl[1] = lo_sum;
    }
  }
  __syncthreads();
}

__device__ __forceinline__ void descend(uint32_t& lo, uint32_t& hi, double& s_hi,
                                        double& s_lo, int sub_shift, Shared& sh) {
  const int t = sh.ictl[kCtlSub];
  const uint32_t base = lo;
  lo = base + (uint32_t(t) << sub_shift);
  hi = base + (uint32_t(t + 1) << sub_shift);
  s_hi = sh.dctl[1];          // S(hi_new)
  s_lo = sh.dctl[1];          // corrected below when the bracket collapses
}
