/bin/bash -lc "cat > submission/solution/kernel.cu <<'EOF'
// Top-p (nucleus) renormalisation of dense row probabilities.
//
// Per row: c = max{v : S(v) >= p}, with S(v) the float64 sum of row entries
// >= v; output is x / S(c) for x >= c, else 0.
//
// One block per row, phases separated by block barriers:
//   A  count + float64 sum histogram over the raw float bit pattern. A bin is
//      2"'^18 patterns wide (~2% in value): fine enough to keep shared-atomic
//      pressure low, coarse enough to bracket the cutoff well.
//   B  descending walk of the histogram -> bracket [lo, hi) holding c with
//      S(hi) < p <= S(lo).
//   C  9-bit descents of that bracket: one pass over the row (which also
//      stages the bracket into shared memory), then shared-only descents.
//   D  elementwise normalised write.
//
// Non-negative floats are ordered by their bit pattern, so all value
// comparisons here are unsigned integer compares of patterns.

#include <torch/extension.h>
#include <c10/cuda/CUDAGuard.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_runtime.h>

#include <cstdint>
#include <mutex>

namespace {

constexpr int kThreads = 1024;
constexpr int kWarps = kThreads / 32;

constexpr int kShift = 18;                 // pattern bits dropped per bin
constexpr uint32_t kTopKey = 0x7F800000u;  // pattern of +inf
constexpr int kNumBins = int(kTopKey >> kShift) + 1;
constexpr int kBinsPerThread = (kNumBins + kThreads - 1) / kThreads;

constexpr int kRefineBits = 9;      // sub-bins per descent
constexpr int kMaxSub = 1 << kRefineBits;
constexpr int kGatherCap = 4096;    // bracket entries staged in shared memory

constexpr int kCtlCross = 0;  // int : crossing bin, -1 if p is never reached
constexpr int kCtlCount = 1;  // int : entries seen inside the bracket
constexpr int kCtlSub = 2;    // int : crossing sub-bin, -1 if absent
constexpr int kCtlPad = 3;

struct Shared {
  uint32_t cnt[kNumBins];
  double sum[kNumBins];
  uint32_t scnt[kMaxSub];
  double ssum[kMaxSub];
  uint32_t staged[kGatherCap];
  double wsum[kWarps];
  double dctl[3];  // [0] S(hi) from the walk, [1] S(hi'"'), [2] S(lo')
  int ictl[4];
};

struct Bracket {
  uint32_t lo;
  uint32_t hi;
  double s_hi;  // S(hi)
  double s_lo;  // S(lo)
};

__device__ __forceinline__ uint32_t key_of(float x) {
  // Negatives, -0.0f and NaN collapse to key 0 and are dropped by any
  // non-negative cutoff, which matches the reference where it is defined.
  return (x >= 0.0f) ? (__float_as_uint(x) & 0x7FFFFFFFu) : 0u;
}

__device__ __forceinline__ uint32_t clamp_key(uint32_t k) {
  return k > kTopKey ? kTopKey : k;
}

// Sum of "'`v` over all lanes/threads that rank above the caller.
__device__ __forceinline__ double block_suffix(double v, double* scratch) {
  constexpr unsigned kFull = 0xFFFFFFFFu;
  const int lane = threadIdx.x & 31;
  const int wid = threadIdx.x >> 5;
  double incl = v;
#pragma unroll
  for (int o = 1; o < 32; o <<= 1) {
    const double t = __shfl_down_sync(kFull, incl, o);
    if (lane + o < 32) incl += t;
  }
  if (lane == 0) scratch[wid] = incl;
  __syncthreads();
  double base = 0.0;
  if (lane == 0) {
    for (int i = wid + 1; i < kWarps; ++i) base += scratch[i];
  }
  base = __shfl_sync(kFull, base, 0);
  return base + (incl - v);
}

__device__ __forceinline__ double block_total(double v, double* scratch) {
  constexpr unsigned kFull = 0xFFFFFFFFu;
  const int lane = threadIdx.x & 31;
  const int wid = threadIdx.x >> 5;
  double incl = v;
#pragma unroll
  for (int o = 1; o < 32; o <<= 1) {
    const double t = __shfl_down_sync(kFull, incl, o);
    if (lane + o < 32) incl += t;
  }
  if (lane == 0) scratch[wid] = incl;
  __syncthreads();
  if (wid == 0) {
    double w = (lane < kWarps) ? scratch[lane] : 0.0;
#pragma unroll
    for (int o = 1; o < 32; o <<= 1) w += __shfl_down_sync(kFull, w, o);
    if (lane == 0) scratch[0] = w;
  }
  __syncthreads();
  const double total = scratch[0];
  __syncthreads();
  return total;
}

// Crossing sub-bin: the unique t with S(lo_t) - s_t < p <= S(lo_t).
// Publishes t, S(hi'"'), S(lo').
__device__ __forceinline__ void sub_walk(int nsub, double s_hi, double p, Shared& sh) {
  const int t = threadIdx.x;
  const double s = (t < nsub) ? sh.ssum[t] : 0.0;
  const double above = s_hi + block_suffix(s, sh.wsum);
  if (t < nsub && above - s < p && above >= p) {
    sh.ictl[kCtlSub] = t;
    sh.dctl[1] = above - s;
    sh.dctl[2] = above;
  }
  __syncthreads();
}

__device__ __forceinline__ void hist_add(Shared& sh, float x) {
  const int b = int(clamp_key(key_of(x)) >> kShift);
  atomicAdd(&sh.cnt[b], 1u);
  if (x > 0.0f) atomicAdd(&sh.sum[b], (double)x);
}

// Stage bracket members, update the sub-histogram, at most kGatherCap values.
__device__ __forceinline__ void stage(Shared& sh, const Bracket& br, int sub_shift, float x) {
  const uint32_t k = clamp_key(key_of(x));
  if (k < br.lo || k >= br.hi) return;
  const int sb = int((k - br.lo) >> sub_shift);
  atomicAdd(&sh.scnt[sb], 1u);
  if (x > 0.0f) atomicAdd(&sh.ssum[sb], (double)x);
  const int pos = atomicAdd(&sh.ictl[kCtlCount], 1);
  if (pos < kGatherCap) sh.staged[pos] = k;
}

__device__ __forceinline__ void descend(Bracket& br, int sub_shift, Shared& sh) {
  const uint32_t base = br.lo;
  const uint32_t t = uint32_t(sh.ictl[kCtlSub]);
  br.lo = base + (t << sub_shift);
  br.hi = base + ((t + 1) << sub_shift);
  br.s_hi = sh.dctl[1];
  br.s_lo = sh.dctl[2];
}

__device__ __forceinline__ void clear_sub(Shared& sh, int nsub) {
  for (int i = threadIdx.x; i < nsub; i += kThreads) {
    sh.scnt[i] = 0u;
    sh.ssum[i] = 0.0;
  }
  if (threadIdx.x == 0) sh.ictl[kCtlSub] = -1;
  __syncthreads();
}

// One descent over the whole row; stages the bracket for later descents.
__device__ void refine_row(const float* __restrict__ in, int V, Bracket& br, double p,
                           Shared& sh) {
  const int span_bits = 31 - __clz(br.hi - br.lo);
  const int bits = span_bits < kRefineBits ? span_bits : kRefineBits;
  const int sub_shift = span_bits - bits;
  const int nsub = 1 << bits;
  clear_sub(sh, nsub);
  if (threadIdx.x == 0) sh.ictl[kCtlCount] = 0;
  __syncthreads();

  const int n4 = V >> 2;
  for (int i = threadIdx.x; i < n4; i += kThreads) {
    const float4 v = reinterpret_cast<const float4*>(in)[i];
    stage(sh, br, sub_shift, v.x);
    stage(sh, br, sub_shift, v.y);
    stage(sh, br, sub_shift, v.z);
    stage(sh, br, sub_shift, v.w);
  }
  for (int i = (n4 << 2) + threadIdx.x; i < V; i += kThreads) stage(sh, br, sub_shift, in[i]);
  __syncthreads();

  sub_walk(nsub, br.s_hi, p, sh);
  descend(br, sub_shift, sh);
}

// Descents done purely on the staged bracket (only valid once complete).
__device__ void refine_staged(int count, Bracket& br, double p, Shared& sh) {
  while (br.hi - br.lo > 1) {
    const int span_bits = 31 - __clz(br.hi - br.lo);
    const int bits = span_bits < kRefineBits ? span_bits : kRefineBits;
    const int sub_shift = span_bits - bits;
    const int nsub = 1 << bits;
    clear_sub(sh, nsub);

    for (int i = threadIdx.x; i < count; i += kThreads) {
      const uint32_t k = sh.staged[i];
      if (k < br.lo || k >= br.hi) continue;
      const int sb = int((k - br.lo) >> sub_shift);
      atomicAdd(&sh.scnt[sb], 1u);
      atomicAdd(&sh.ssum[sb], (double)__uint_as_float(k));
    }
    __syncthreads();

    sub_walk(nsub, br.s_hi, p, sh);
    descend(br, sub_shift, sh);
  }
}

__global__ void top_p_renorm(const float* __restrict__ probs, int64_t pitch,
                             const float* __restrict__ top_p,
                             float* __restrict__ out, int64_t opitch, int V) {
  extern __shared__ char raw[];
  Shared& sh = *reinterpret_cast<Shared*>(raw);
  const float* __restrict__ in = probs + int64_t(blockIdx.x) * pitch;
  float* __restrict__ op = out + int64_t(blockIdx.x) * opitch;
  const double p = double(top_p[blockIdx.x]);
  const int n4 = V >> 2;

  // Phase A: histogram the row.
  for (int i = threadIdx.x; i < kNumBins; i += kThreads) {
    sh.cnt[i] = 0u;
    sh.sum[i] = 0.0;
  }
  if (threadIdx.x < kMaxSub) {
    sh.scnt[threadIdx.x] = 0u;
    sh.ssum[threadIdx.x] = 0.0;
  }
  if (threadIdx.x < 3) sh.dctl[threadIdx.x] = 0.0;
  if (threadIdx.x < 4) {
    sh.ictl[threadIdx.x] = (threadIdx.x == kCtlCross || threadIdx.x == kCtlSub) ? -1 : 0;
  }
  __syncthreads();

  for (int i = threadIdx.x; i < n4; i += kThreads) {
    const float4 v = reinterpret_cast<const float4*>(in)[i];
    hist_add(sh, v.x);
    hist_add(sh, v.y);
    hist_add(sh, v.z);
    hist_add(sh, v.w);
  }
  for (int i = (n4 << 2) + threadIdx.x; i < V; i += kThreads) hist_add(sh, in[i]);
  __syncthreads();

  // Phase B: descending walk for the bin holding the cutoff.
  double group = 0.0;
  const int b0 = threadIdx.x * kBinsPerThread;
#pragma unroll
  for (int j = 0; j < kBinsPerThread; ++j) {
    const int b = b0 + j;
    if (b < kNumBins) group += sh.sum[b];
  }
  const double above_groups = block_suffix(group, sh.wsum);
  double acc = 0.0;
#pragma unroll
  for (int j = kBinsPerThread - 1; j >= 0; --j) {
    const int b = b0 + j;
    if (b >= kNumBins) continue;
    const double s = sh.sum[b];
    const double hi_sum = above_groups + acc;
    if (hi_sum < p && hi_sum + s >= p) {
      sh.ictl[kCtlCross] = b;
      sh.dctl[0] = hi_sum;
    }
    acc += s;
  }
  __syncthreads();

  float cutoff;
  double s_cut;
  const int cross = sh.ictl[kCtlCross];
  if (cross < 0) {
    // p is never reached: the reference clamps to the last token, which keeps
    // the whole row. Cutoff 0 keeps every non-negative entry.
    cutoff = 0.0f;
    s_cut = block_total(group, sh.wsum);
  } else {
    Bracket br;
    br.lo = uint32_t(cross) << kShift;
    br.hi = br.lo + (1u << kShift);
    br.s_hi = sh.dctl[0];
    br.s_lo = 0.0;

    refine_row(in, V, br, p, sh);
    while (br.hi - br.lo > 1) {
      if (sh.ictl[kCtlCount] <= kGatherCap) {
        refine_staged(sh.ictl[kCtlCount], br, p, sh);
      } else {
        refine_row(in, V, br, p, sh);
      }
    }
    cutoff = __uint_as_float(br.lo);
    s_cut = br.s_lo;
  }

  // Phase D: normalised write.
  const float inv = (s_cut > 0.0) ? float(1.0 / s_cut) : 0.0f;
  const float cut = cutoff;
  for (int i = threadIdx.x; i < n4; i += kThreads) {
    const float4 v = reinterpret_cast<const float4*>(in)[i];
    float4 w;
    w.x = (v.x >= cut) ? v.x * inv : 0.0f;
    w.y = (v.y >= cut) ? v.y * inv : 0.0f;
    w.z = (v.z >= cut) ? v.z * inv : 0.0f;
    w.w = (v.w >= cut) ? v.w * inv : 0.0f;
    reinterpret_cast<float4*>(op)[i] = w;
  }
  for (int i = (n4 << 2) + threadIdx.x; i < V; i += kThreads) {
    const float x = in[i];
    op[i] = (x >= cut) ? x * inv : 0.0f;
  }
}

constexpr int kSharedBytes = sizeof(Shared);

void configure_once() {
  static std::once_flag once;
  std::call_once(once, [] {
    const cudaError_t err = cudaFuncSetAttribute(
        top_p_renorm, cudaFuncAttributeMaxDynamicSharedMemorySize, kSharedBytes);
    TORCH_CHECK(err == cudaSuccess, \"shared attribute: \", cudaGetErrorString(err));
  });
}

void kernel(const torch::Tensor& probs, const torch::Tensor& top_p,
            const torch::Tensor& out) {
  TORCH_CHECK(probs.is_cuda() && top_p.is_cuda() && out.is_cuda(), \"CUDA tensors required\");
  TORCH_CHECK(probs.scalar_type() == torch::kFloat32 && top_p.scalar_type() == torch::kFloat32 &&
                  out.scalar_type() == torch::kFloat32,
              \"float32 required\");
  TORCH_CHECK(probs.dim() == 2 && out.dim() == 2, \"rank 2 inputs and outputs\");
  TORCH_CHECK(top_p.dim() == 1, \"rank 1 top_p\");
  const int64_t rows = probs.size(0);
  const int64_t cols = probs.size(1);
  TORCH_CHECK(out.size(0) == rows && out.size(1) == cols, \"output shape mismatch\");
  TORCH_CHECK(top_p.size(0) == rows, \"top_p shape mismatch\");
  TORCH_CHECK(probs.stride(1) == 1 && out.stride(1) == 1 && top_p.stride(0) == 1,
              \"unit inner stride required\");
  TORCH_CHECK(probs.device() == out.device() && probs.device() == top_p.device(),
              \"device mismatch\");
  if (rows == 0 || cols == 0) return;

  c10::cuda::CUDAGuard guard(probs.device());
  configure_once();
  const cudaStream_t stream = c10::cuda::getCurrentCUDAStream(probs.get_device()).stream();
  top_p_renorm<<<uint32_t(rows), kThreads, kSharedBytes, stream>>>(
      probs.data_ptr<float>(), probs.stride(0), top_p.data_ptr<float>(),
      out.data_ptr<float>(), out.stride(0), int(cols));
  const cudaError_t err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, \"top_p launch: \", cudaGetErrorString(err));
}

}  // namespace

