constexpr uint32_t kTopKey = 0x7F800000u;  // pattern of +inf
constexpr int kNumBins = int(kTopKey >> kShift) + 1;
constexpr int kBinsPerThread = (kNumBins + kThreads - 1) / kThreads;
constexpr uint32_t kBinSpan = 1u << kShift;

constexpr int kRefineBits = 9;    // sub-bins per descent
constexpr int kMaxSub = 1 << kRefineBits;
constexpr int kWindow = 3;        // bins staged around the centre bin
constexpr int kGatherCap = 6144;  // staged entries (3 typical bins hold ~3200)

constexpr int kCtlCross = 0;  // int : centre bin, -1 if p is never reached
constexpr int kCtlCount = 1;  // int : entries seen inside the staged window
constexpr int kCtlSub = 2;    // int : crossing sub-bin, -1 if absent
constexpr int kCtlFound = 3;  // int : 1 once the crossing bin is pinned

struct Shared {
  float sum[kNumBins];
  float ssum[kMaxSub];
