  // non-negative cutoff, which matches the reference where it is defined.
  return (x >= 0.0f) ? (__float_as_uint(x) & 0x7FFFFFFFu) : 0u;
}

__device__ __forceinline__ uint32_t clamp_key(uint32_t k) {
  return k > kTopKey ? kTopKey : k;
