__global__ void top_p_renorm(const float* __restrict__ probs, int64_t pitch,
                             const float* __restrict__ top_p,
                             float* __restrict__ out, int64_t opitch, int V) {
  extern __shared__ char raw[];
  Shared& sh = *reinterpret_cast<Shared*>(raw);
  const float* __restrict__ in = probs + int64_t(blockIdx.x) * pitch;
  float* __restrict__ op = out + int64_t(blockIdx.x) * opitch;
  const double p = double(top_p[blockIdx.x]);
  const int n4 = V >> 2;

  // Phase A: histogram the row.
  for (int i = threadIdx.x; i < kNumBins; i += kThreads) sh.sum[i] = 0.0f;
  if (threadIdx.x < kMaxSub) sh.ssum[threadIdx.x] = 0.0f;
  if (threadIdx.x < 3) sh.dctl[threadIdx.x] = 0.0;
  if (threadIdx.x < 4) {
    sh.ictl[threadIdx.x] = (threadIdx.x == kCtlCross || threadIdx.x == kCtlSub) ? -1 : 0;
  }
  __syncthreads();

  const bool vec = vector_ok(in, pitch);
  if (vec) {
    for (int i = threadIdx.x; i < n4; i += kThreads) {
      const float4 v = reinterpret_cast<const float4*>(in)[i];
      hist_add(sh, v.x);
      hist_add(sh, v.y);
      hist_add(sh, v.z);
      hist_add(sh, v.w);
    }
    for (int i = (n4 << 2) + threadIdx.x; i < V; i += kThreads) hist_add(sh, in[i]);
  } else {
    for (int i = threadIdx.x; i < V; i += kThreads) hist_add(sh, in[i]);
  }
  __syncthreads();

  // Phase B: descending walk for the bin holding the cutoff.
  double group = 0.0;
  const int b0 = threadIdx.x * kBinsPerThread;
#pragma unroll
  for (int j = 0; j < kBinsPerThread; ++j) {
    const int b = b0 + j;
    if (b < kNumBins) group += double(sh.sum[b]);
  }
  const double above_groups = block_suffix(group, sh.wsum);
  double acc = 0.0;
#pragma unroll
  for (int j = kBinsPerThread - 1; j >= 0; --j) {
    const int b = b0 + j;
    if (b >= kNumBins) continue;
    const double s = double(sh.sum[b]);
    const double hi_sum = above_groups + acc;
    if (hi_sum < p && hi_sum + s >= p) {
      sh.ictl[kCtlCross] = b;
      sh.dctl[0] = hi_sum;
    }
    acc += s;
  }
  __syncthreads();

  float cutoff;
  double s_cut;
  int cross = sh.ictl[kCtlCross];
  if (cross < 0) {
    // p is never reached: the reference clamps to the last token, which keeps
    // the whole row. Cutoff 0 keeps every non-negative entry.
    cutoff = 0.0f;
    s_cut = block_total(group, sh.wsum);
  } else {
    // Phase C: pin the crossing bin exactly from the staged window, widening
    // the window if the (float32) histogram walk mis-placed it.
    window_pass(in, V, vec, cross, p, sh);
    int bin = pin_bin(cross, p, sh);
    for (int attempt = 0; attempt < 8 && bin < 0; ++attempt) {
      // Anchor the histogram walk on the exact sum above the centre bin top.
      const double anchor = sh.dctl[0];
      int nb = cross;
      if (anchor >= p) {
        double t = anchor;
        for (int b = cross + 1; b < kNumBins; ++b) {
          t -= double(sh.sum[b]);
          if (t < p) {
            nb = b;
            break;
          }
        }
      } else {
        double t = anchor;
        for (int b = cross - 1; b >= 0; --b) {
          t += double(sh.sum[b + 1]);
          if (t >= p) {
            nb = b;
            break;
          }
        }
      }
      if (nb == cross) break;
      cross = nb;
      window_pass(in, V, vec, cross, p, sh);
      bin = pin_bin(cross, p, sh);
    }

    Bracket br;
    br.lo = uint32_t(cross) << kShift;
    br.hi = br.lo + kBinSpan;
    br.s_hi = sh.dctl[0];
    br.s_lo = 0.0;
    const int count = sh.ictl[kCtlCount];
    if (count <= kGatherCap) {
      refine_staged(count, br, p, sh);
    } else {
      for (int i = threadIdx.x; i < kNumBins; i += kThreads) sh.sum[i] = 0.0f;
      if (threadIdx.x < kMaxSub) sh.ssum[threadIdx.x] = 0.0f;
      __syncthreads();
      refine_row(in, V, vec, br, p, sh);
      if (sh.ictl[kCtlCount] <= kGatherCap) refine_staged(sh.ictl[kCtlCount], br, p, sh);
      else refine_row(in, V, vec, br, p, sh);
    }
    cutoff = __uint_as_float(br.lo);
    s_cut = br.s_lo;
  }

  // Phase E: normalised write.
  const float inv = (s_cut > 0.0) ? float(1.0 / s_cut) : 0.0f;
  const float cut = cutoff;
