// Accumulate a bracket entry into its sub-bin, as a fixed-point code relative
// to the bracket base. Codes compare and sum exactly; only the double
// conversion at walk time rounds.
__device__ __forceinline__ void sub_add(Shared& sh, uint32_t k, uint32_t base_key,
                                        int slot) {
  const uint32_t code = (k - base_key) >> kCodeShift;
  atomicAdd(&sh.sub_hi[slot], code >> kHiShift);
  atomicAdd(&sh.sub_lo[slot], code & kLoMask);
}

__device__ __forceinline__ uint32_t bracket_base_key(uint32_t base) {
  const int e = int(base >> 23);
  return uint32_t(e > 1 ? e - 1 : 0) << 23;
}

__device__ __forceinline__ void clear_sub(Shared& sh, int nsub) {
  for (int i = threadIdx.x; i < nsub; i += kThreads) {
    sh.sub_hi[i] = 0u;
    sh.sub_lo[i] = 0u;
  }
  if (threadIdx.x == 0) sh.ictl[kCtlSub] = -1;
  __syncthreads();
}

// Stage the kWindow bins around `centre` and measure the exact sums at the
// window edges. Publishes staged entries in sh.staged and the exact anchor
// S(top(centre)) in dctl[0].
__device__ void window_pass(const float* __restrict__ in, int V, bool vec, int centre,
                            double p, Shared& sh) {
  const uint32_t top_centre = (uint32_t(centre) + 1u) << kShift;
  const uint32_t win_lo = (centre >= 1 ? uint32_t(centre - 1) : 0u) << kShift;
  uint32_t win_hi = (uint32_t(centre) + 2u) << kShift;
  if (win_hi > kTopKey) win_hi = kTopKey + 1u;

  if (threadIdx.x == 0) sh.ictl[kCtlCount] = 0;
  __syncthreads();

  double above = 0.0;
  if (vec) {
    const int n4 = V >> 2;
    for (int i = threadIdx.x; i < n4; i += kThreads) {
      const float4 v = reinterpret_cast<const float4*>(in)[i];
#pragma unroll
      for (int c = 0; c < 4; ++c) {
        const float x = (c == 0) ? v.x : (c == 1) ? v.y : (c == 2) ? v.z : v.w;
        if (!(x > 0.0f)) continue;

// Top-p (nucleus) renormalisation of dense row probabilities.
//
// Per row: c = max{v : S(v) >= p}, with S(v) the float64 sum of row entries
// >= v; output is x / S(c) for x >= c, else 0.
//
// One block per row, phases separated by block barriers:
//   A  sum histogram over the raw float bit pattern. A bin is 2^18 patterns
//      wide (~2% in value): fine enough to keep shared-atomic pressure low,
//      coarse enough to bracket the cutoff to within a bin.
//   B  descending walk of that histogram -> centre bin, plus the bin indices
//      where the sum crosses p.
//   C  one pass over the row: exact float64 sum above the centre bin's top edge
//      and staging of the three bins around it. The staged entries are enough
//      to pin the crossing bin and the cutoff exactly; the walk in B only has
//      to be accurate to a bin, which float32 bin sums are.
//   D  shared-memory descents of the bracket down to a single float pattern.
//   E  elementwise normalised write.
//
// Non-negative floats are ordered by their bit pattern, so all value
// comparisons here are unsigned integer compares of patterns.

#include <torch/extension.h>
#include <c10/cuda/CUDAGuard.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_runtime.h>

#include <cstdint>
#include <mutex>

namespace {

constexpr int kThreads = 1024;
constexpr int kWarps = kThreads / 32;

constexpr int kShift = 18;                 // pattern bits dropped per bin
constexpr uint32_t kTopKey = 0x7F800000u;  // pattern of +inf
constexpr int kNumBins = int(kTopKey >> kShift) + 1;
constexpr int kBinsPerThread = (kNumBins + kThreads - 1) / kThreads;
constexpr uint32_t kBinSpan = 1u << kShift;

constexpr int kRefineBits = 9;    // sub-bins per descent
constexpr int kMaxSub = 1 << kRefineBits;
constexpr int kWindow = 3;        // bins staged around the centre bin
constexpr int kGatherCap = 6144;  // staged entries (3 typical bins hold ~3200)

// Shared-memory atomics are integer only on this target: atomicAdd(float*)
// lowers to a compare-and-swap spin loop. Bin masses are therefore carried as
// 32-bit fixed-point mantissa codes, split hi/lo so neither word can overflow.
//
//   code(x) = 2^22 + top22(mantissa)        in [2^22, 2^23)
//   mass    = (hi * 2^8 + lo) * 2^(e - 149)
//
// A bin of 2^18 patterns stays inside one binade, so its exponent is b >> 5.
constexpr int kCodeFrac = 22;  // mantissa bits kept in a code
constexpr uint32_t kCodeOne = 1u << kCodeFrac;
constexpr int kHiShift = 8;  // low bits split off to keep both words in range
constexpr uint32_t kLoMask = (1u << kHiShift) - 1;
constexpr double kExpBias = 127.0 + kCodeFrac;
constexpr int kCodeShift = 23 - kCodeFrac;  // mantissa bits dropped

constexpr int kCtlCross = 0;  // int : centre bin, -1 if p is never reached
constexpr int kCtlCount = 1;  // int : entries seen inside the staged window
constexpr int kCtlSub = 2;    // int : crossing sub-bin, -1 if absent
constexpr int kCtlFound = 3;  // int : 1 once the crossing bin is pinned

struct Shared {
  uint32_t bin_hi[kNumBins];
  uint32_t bin_lo[kNumBins];
  uint32_t sub_hi[kMaxSub];
  uint32_t sub_lo[kMaxSub];
  uint32_t staged[kGatherCap];
  double wsum[kWarps];
  double dctl[3];  // [0] S(hi), [1] S(hi'), [2] S(lo')
  int ictl[4];
};

struct Bracket {
  uint32_t lo;
  uint32_t hi;
  double s_hi;  // S(hi)
  double s_lo;  // S(lo)
};

__device__ __forceinline__ uint32_t clamp_key(uint32_t k) {
  return k > kTopKey ? kTopKey : k;
}

__device__ __forceinline__ double val_of(uint32_t k) {
  return double(__uint_as_float(k));
}

// Value of the binade holding `base`, as a factor for fixed-point codes.
__device__ __forceinline__ double scale_of(uint32_t base) {
  const int e = int(base >> 23);
  return ldexp(1.0, (e > 1 ? e : 1) - kExpBias);
}

__device__ __forceinline__ double mass_of(uint32_t hi, uint32_t lo, double scale) {
  return (double(hi) * double(1u << kHiShift) + double(lo)) * scale;
}

__device__ __forceinline__ double bin_mass(const Shared& sh, int b) {
  return mass_of(sh.bin_hi[b], sh.bin_lo[b], scale_of(uint32_t(b) << kShift));
}

// Fixed-point code of a positive value; 0 is reported as exponent 1 so the
// codes of a bracket never shift below zero.
__device__ __forceinline__ uint32_t code_of(uint32_t k) {
  return ((k >> kCodeShift) & (kCodeOne - 1u)) | kCodeOne;
}

// Sum of `v` over all lanes/threads that rank above the caller.
__device__ __forceinline__ double block_suffix(double v, double* scratch) {
  constexpr unsigned kFull = 0xFFFFFFFFu;
  const int lane = threadIdx.x & 31;
  const int wid = threadIdx.x >> 5;
  double incl = v;
#pragma unroll
  for (int o = 1; o < 32; o <<= 1) {
    const double t = __shfl_down_sync(kFull, incl, o);
    if (lane + o < 32) incl += t;
  }
  if (lane == 0) scratch[wid] = incl;
  __syncthreads();
  double base = 0.0;
  if (lane == 0) {
    for (int i = wid + 1; i < kWarps; ++i) base += scratch[i];
  }
  base = __shfl_sync(kFull, base, 0);
  return base + (incl - v);
}

__device__ __forceinline__ double block_total(double v, double* scratch) {
  constexpr unsigned kFull = 0xFFFFFFFFu;
  const int lane = threadIdx.x & 31;
  const int wid = threadIdx.x >> 5;
  double incl = v;
#pragma unroll
  for (int o = 1; o < 32; o <<= 1) {
    const double t = __shfl_down_sync(kFull, incl, o);
    if (lane + o < 32) incl += t;
  }
  if (lane == 0) scratch[wid] = incl;
  __syncthreads();
  if (wid == 0) {
    double w = (lane < kWarps) ? scratch[lane] : 0.0;
#pragma unroll
    for (int o = 1; o < 32; o <<= 1) w += __shfl_down_sync(kFull, w, o);
    if (lane == 0) scratch[0] = w;
  }
  __syncthreads();
  const double total = scratch[0];
  __syncthreads();
  return total;
}

// Crossing sub-bin: the unique t with S(hi_t) < p <= S(lo_t).
__device__ __forceinline__ void sub_walk(int nsub, uint32_t base, double s_hi, double p,
                                         Shared& sh) {
  const int t = threadIdx.x;
  const double scale = scale_of(base);
  const double s = (t < nsub) ? mass_of(sh.sub_hi[t], sh.sub_lo[t], scale) : 0.0;
  const double hi_sum = s_hi + block_suffix(s, sh.wsum);
  const double lo_sum = hi_sum + s;
  if (t < nsub && hi_sum < p && lo_sum >= p) {
    sh.ictl[kCtlSub] = t;
    sh.dctl[1] = hi_sum;
    sh.dctl[2] = lo_sum;
  }
  __syncthreads();
}

__device__ __forceinline__ void hist_add(Shared& sh, float x) {
  if (!(x > 0.0f)) return;
  const uint32_t k = __float_as_uint(x);
  const uint32_t code = code_of(k);
  const int b = int(k >> kShift);
  atomicAdd(&sh.bin_hi[b], code >> kHiShift);
  atomicAdd(&sh.bin_lo[b], code & kLoMask);
}

__device__ __forceinline__ bool vector_ok(const float* __restrict__ in, int64_t pitch) {
  return ((pitch & 3) == 0) && ((reinterpret_cast<uintptr_t>(in) & 15u) == 0);
}

__device__ __forceinline__ void descend(Bracket& br, int sub_shift, Shared& sh) {
  const uint32_t base = br.lo;
  const uint32_t t = uint32_t(sh.ictl[kCtlSub]);
  br.lo = base + (t << sub_shift);
  br.hi = base + ((t + 1) << sub_shift);
  br.s_hi = sh.dctl[1];
  br.s_lo = sh.dctl[2];
}

// Accumulate a bracket entry into its sub-bin, as a fixed-point code relative
// to the bracket base. Codes compare and sum exactly; only the double
// conversion at walk time rounds.
__device__ __forceinline__ void sub_add(Shared& sh, uint32_t k, uint32_t base_key,
                                        int slot) {
  const uint32_t code = (k - base_key) >> kCodeShift;
  atomicAdd(&sh.sub_hi[slot], code >> kHiShift);
  atomicAdd(&sh.sub_lo[slot], code & kLoMask);
}

__device__ __forceinline__ uint32_t bracket_base_key(uint32_t base) {
  const int e = int(base >> 23);
  return uint32_t(e > 1 ? e - 1 : 0) << 23;
}

__device__ __forceinline__ void clear_sub(Shared& sh, int nsub) {
  for (int i = threadIdx.x; i < nsub; i += kThreads) {
    sh.sub_hi[i] = 0u;
    sh.sub_lo[i] = 0u;
  }
  if (threadIdx.x == 0) sh.ictl[kCtlSub] = -1;
  __syncthreads();
}

// Stage the kWindow bins around `centre` and measure the exact sums at the
// window edges. Publishes staged entries in sh.staged and the exact anchor
// S(top(centre)) in dctl[0].
__device__ void window_pass(const float* __restrict__ in, int V, bool vec, int centre,
                            double p, Shared& sh) {
  const uint32_t top_centre = (uint32_t(centre) + 1u) << kShift;
  const uint32_t win_lo = (centre >= 1 ? uint32_t(centre - 1) : 0u) << kShift;
  uint32_t win_hi = (uint32_t(centre) + 2u) << kShift;
  if (win_hi > kTopKey) win_hi = kTopKey + 1u;

  if (threadIdx.x == 0) sh.ictl[kCtlCount] = 0;
  __syncthreads();

  double above = 0.0;
  if (vec) {
    const int n4 = V >> 2;
    for (int i = threadIdx.x; i < n4; i += kThreads) {
      const float4 v = reinterpret_cast<const float4*>(in)[i];
#pragma unroll
      for (int c = 0; c < 4; ++c) {
        const float x = (c == 0) ? v.x : (c == 1) ? v.y : (c == 2) ? v.z : v.w;
        if (!(x > 0.0f)) continue;
        const uint32_t k = clamp_key(__float_as_uint(x) & 0x7FFFFFFFu);
        if (k >= top_centre) above += double(x);
        if (k >= win_lo && k < win_hi) {
          const int pos = atomicAdd(&sh.ictl[kCtlCount], 1);
          if (pos < kGatherCap) sh.staged[pos] = k;
        }
      }
    }
    for (int i = (n4 << 2) + threadIdx.x; i < V; i += kThreads) {
      const float x = in[i];
      if (!(x > 0.0f)) continue;
      const uint32_t k = clamp_key(__float_as_uint(x) & 0x7FFFFFFFu);
      if (k >= top_centre) above += double(x);
      if (k >= win_lo && k < win_hi) {
        const int pos = atomicAdd(&sh.ictl[kCtlCount], 1);
        if (pos < kGatherCap) sh.staged[pos] = k;
      }
    }
  } else {
    for (int i = threadIdx.x; i < V; i += kThreads) {
      const float x = in[i];
      if (!(x > 0.0f)) continue;
      const uint32_t k = clamp_key(__float_as_uint(x) & 0x7FFFFFFFu);
      if (k >= top_centre) above += double(x);
      if (k >= win_lo && k < win_hi) {
        const int pos = atomicAdd(&sh.ictl[kCtlCount], 1);
        if (pos < kGatherCap) sh.staged[pos] = k;
      }
    }
  }
  const double anchor = block_total(above, sh.wsum);
  __syncthreads();
  if (threadIdx.x == 0) sh.dctl[0] = anchor;
  __syncthreads();
}

// Exact per-bin sums of the staged window plus the crossing bin, or -1 when
// the crossing lies outside the window.
__device__ int pin_bin(int centre, double p, Shared& sh) {
  const double anchor = sh.dctl[0];  // S(top(centre))
  const int count = sh.ictl[kCtlCount];
  const uint32_t top_centre = (uint32_t(centre) + 1u) << kShift;
  const uint32_t win_lo = (centre >= 1 ? uint32_t(centre - 1) : 0u) << kShift;

  double prev = 0.0, cur = 0.0, next = 0.0;
  for (int i = threadIdx.x; i < count; i += kThreads) {
    const uint32_t k = sh.staged[i];
    if (k < win_lo + kBinSpan) prev += val_of(k);
    else if (k < top_centre) cur += val_of(k);
    else next += val_of(k);
  }
  const double s_prev = block_total(prev, sh.wsum);
  const double s_cur = block_total(cur, sh.wsum);
  const double s_next = block_total(next, sh.wsum);

  const double s_top_prev = anchor + s_cur;        // S(top(centre-1))
  const double s_top_next = anchor - s_next;       // S(top(centre+1))
  int bin = -1;
  double s_hi = 0.0;
  if (anchor < p && s_top_prev >= p) {
    bin = centre;
    s_hi = anchor;
  } else if (s_top_prev < p && s_top_prev + s_prev >= p) {
    bin = centre - 1;
    s_hi = s_top_prev;
  } else if (s_top_next < p && anchor >= p) {
    bin = centre + 1;
    s_hi = s_top_next;
  }
  if (threadIdx.x == 0 && bin >= 0) {
    sh.ictl[kCtlCross] = bin;
    sh.dctl[0] = s_hi;
    sh.ictl[kCtlFound] = 1;
  }
  __syncthreads();
  return bin;
}

// Descents done purely on the staged bracket (only valid once complete).
__device__ void refine_staged(int count, Bracket& br, double p, Shared& sh) {
  while (br.hi - br.lo > 1) {
    const int span_bits = 31 - __clz(br.hi - br.lo);
    const int bits = span_bits < kRefineBits ? span_bits : kRefineBits;
    const int sub_shift = span_bits - bits;
    const int nsub = 1 << bits;
    clear_sub(sh, nsub);
    const uint32_t base_key = bracket_base_key(br.lo);

    for (int i = threadIdx.x; i < count; i += kThreads) {
      const uint32_t k = sh.staged[i];
      if (k < br.lo || k >= br.hi) continue;
      sub_add(sh, k, base_key, int((k - br.lo) >> sub_shift));
    }
    __syncthreads();

    sub_walk(nsub, br.lo, br.s_hi, p, sh);
    descend(br, sub_shift, sh);
  }
}

// One descent over the whole row; stages the bracket for later descents.
__device__ void refine_row(const float* __restrict__ in, int V, bool vec, Bracket& br,
                           double p, Shared& sh) {
  const int span_bits = 31 - __clz(br.hi - br.lo);
  const int bits = span_bits < kRefineBits ? span_bits : kRefineBits;
  const int sub_shift = span_bits - bits;
  const int nsub = 1 << bits;
  clear_sub(sh, nsub);
  if (threadIdx.x == 0) sh.ictl[kCtlCount] = 0;
  __syncthreads();

  const uint32_t lo = br.lo, hi = br.hi;
  const uint32_t base_key = bracket_base_key(lo);
  if (vec) {
    const int n4 = V >> 2;
    for (int i = threadIdx.x; i < n4; i += kThreads) {
      const float4 v = reinterpret_cast<const float4*>(in)[i];
#pragma unroll
      for (int c = 0; c < 4; ++c) {
        const float x = (c == 0) ? v.x : (c == 1) ? v.y : (c == 2) ? v.z : v.w;
        if (!(x > 0.0f)) continue;
        const uint32_t k = clamp_key(__float_as_uint(x) & 0x7FFFFFFFu);
        if (k < lo || k >= hi) continue;
        sub_add(sh, k, base_key, int((k - lo) >> sub_shift));
        const int pos = atomicAdd(&sh.ictl[kCtlCount], 1);
        if (pos < kGatherCap) sh.staged[pos] = k;
      }
    }
    for (int i = (n4 << 2) + threadIdx.x; i < V; i += kThreads) {
      const float x = in[i];
      if (!(x > 0.0f)) continue;
      const uint32_t k = clamp_key(__float_as_uint(x) & 0x7FFFFFFFu);
      if (k < lo || k >= hi) continue;
      sub_add(sh, k, base_key, int((k - lo) >> sub_shift));
      const int pos = atomicAdd(&sh.ictl[kCtlCount], 1);
      if (pos < kGatherCap) sh.staged[pos] = k;
    }
  } else {
    for (int i = threadIdx.x; i < V; i += kThreads) {
      const float x = in[i];
      if (!(x > 0.0f)) continue;
      const uint32_t k = clamp_key(__float_as_uint(x) & 0x7FFFFFFFu);
      if (k < lo || k >= hi) continue;
      sub_add(sh, k, base_key, int((k - lo) >> sub_shift));
      const int pos = atomicAdd(&sh.ictl[kCtlCount], 1);
      if (pos < kGatherCap) sh.staged[pos] = k;
    }
  }
  __syncthreads();

  sub_walk(nsub, br.lo, br.s_hi, p, sh);
  descend(br, sub_shift, sh);
}

__global__ void top_p_renorm(const float* __restrict__ probs, int64_t pitch,
                             const float* __restrict__ top_p,
                             float* __restrict__ out, int64_t opitch, int V) {
  extern __shared__ char raw[];
  Shared& sh = *reinterpret_cast<Shared*>(raw);
  const float* __restrict__ in = probs + int64_t(blockIdx.x) * pitch;
  float* __restrict__ op = out + int64_t(blockIdx.x) * opitch;
  const double p = double(top_p[blockIdx.x]);
  const int n4 = V >> 2;

  // Phase A: histogram the row.
  for (int i = threadIdx.x; i < kNumBins; i += kThreads) {
    sh.bin_hi[i] = 0u;
    sh.bin_lo[i] = 0u;
  }
  if (threadIdx.x < 3) sh.dctl[threadIdx.x] = 0.0;
  if (threadIdx.x < 4) {
    sh.ictl[threadIdx.x] = (threadIdx.x == kCtlCross || threadIdx.x == kCtlSub) ? -1 : 0;
  }
  __syncthreads();

  const bool vec = vector_ok(in, pitch);
  if (vec) {
    for (int i = threadIdx.x; i < n4; i += kThreads) {
      const float4 v = reinterpret_cast<const float4*>(in)[i];
      hist_add(sh, v.x);
      hist_add(sh, v.y);
      hist_add(sh, v.z);
      hist_add(sh, v.w);
    }
    for (int i = (n4 << 2) + threadIdx.x; i < V; i += kThreads) hist_add(sh, in[i]);
  } else {
    for (int i = threadIdx.x; i < V; i += kThreads) hist_add(sh, in[i]);
  }
  __syncthreads();

  // Phase B: descending walk for the bin holding the cutoff.
  double group = 0.0;
  const int b0 = threadIdx.x * kBinsPerThread;
#pragma unroll
  for (int j = 0; j < kBinsPerThread; ++j) {
    const int b = b0 + j;
    if (b < kNumBins) group += bin_mass(sh, b);
  }
  const double above_groups = block_suffix(group, sh.wsum);
  double acc = 0.0;
#pragma unroll
  for (int j = kBinsPerThread - 1; j >= 0; --j) {
    const int b = b0 + j;
    if (b >= kNumBins) continue;
    const double s = bin_mass(sh, b);
    const double hi_sum = above_groups + acc;
    if (hi_sum < p && hi_sum + s >= p) {
      sh.ictl[kCtlCross] = b;
      sh.dctl[0] = hi_sum;
    }
    acc += s;
  }
  __syncthreads();

  float cutoff;
  double s_cut;
  int cross = sh.ictl[kCtlCross];
  if (cross < 0) {
    // p is never reached: the reference clamps to the last token, which keeps
    // the whole row. Cutoff 0 keeps every non-negative entry.
    cutoff = 0.0f;
    s_cut = block_total(group, sh.wsum);
  } else {
    // Phase C: pin the crossing bin exactly from the staged window, widening
    // the window if the (float32) histogram walk mis-placed it.
    window_pass(in, V, vec, cross, p, sh);
    int bin = pin_bin(cross, p, sh);
    for (int attempt = 0; attempt < 8 && bin < 0; ++attempt) {
      // Anchor the histogram walk on the exact sum above the centre bin top.
      const double anchor = sh.dctl[0];
      int nb = cross;
      if (anchor >= p) {
        double t = anchor;
        for (int b = cross + 1; b < kNumBins; ++b) {
          t -= bin_mass(sh, b);
          if (t < p) {
            nb = b;
            break;
          }
        }
      } else {
        double t = anchor;
        for (int b = cross - 1; b >= 0; --b) {
          t += bin_mass(sh, b + 1);
          if (t >= p) {
            nb = b;
            break;
          }
        }
      }
      if (nb == cross) break;
      cross = nb;
      window_pass(in, V, vec, cross, p, sh);
      bin = pin_bin(cross, p, sh);
    }

    Bracket br;
    br.lo = uint32_t(cross) << kShift;
    br.hi = br.lo + kBinSpan;
    br.s_hi = sh.dctl[0];
    br.s_lo = 0.0;
    const int count = sh.ictl[kCtlCount];
    if (count <= kGatherCap) {
      refine_staged(count, br, p, sh);
    } else {
      for (int i = threadIdx.x; i < kNumBins; i += kThreads) {
        sh.bin_hi[i] = 0u;
        sh.bin_lo[i] = 0u;
      }
      __syncthreads();
      refine_row(in, V, vec, br, p, sh);
      if (sh.ictl[kCtlCount] <= kGatherCap) refine_staged(sh.ictl[kCtlCount], br, p, sh);
      else refine_row(in, V, vec, br, p, sh);
    }
    cutoff = __uint_as_float(br.lo);
    s_cut = br.s_lo;
  }

  // Phase E: normalised write.
  const float inv = (s_cut > 0.0) ? float(1.0 / s_cut) : 0.0f;
  const float cut = cutoff;
  if (vec) {
    for (int i = threadIdx.x; i < n4; i += kThreads) {
      const float4 v = reinterpret_cast<const float4*>(in)[i];
      float4 w;
      w.x = (v.x >= cut) ? v.x * inv : 0.0f;
      w.y = (v.y >= cut) ? v.y * inv : 0.0f;
      w.z = (v.z >= cut) ? v.z * inv : 0.0f;
      w.w = (v.w >= cut) ? v.w * inv : 0.0f;
      reinterpret_cast<float4*>(op)[i] = w;
    }
    for (int i = (n4 << 2) + threadIdx.x; i < V; i += kThreads) {
      const float x = in[i];
      op[i] = (x >= cut) ? x * inv : 0.0f;
    }
  } else {
    for (int i = threadIdx.x; i < V; i += kThreads) {
      const float x = in[i];
      op[i] = (x >= cut) ? x * inv : 0.0f;
    }
  }
}

constexpr int kSharedBytes = sizeof(Shared);

void configure_once() {
  static std::once_flag once;
  std::call_once(once, [] {
    const cudaError_t err = cudaFuncSetAttribute(
        top_p_renorm, cudaFuncAttributeMaxDynamicSharedMemorySize, kSharedBytes);
    TORCH_CHECK(err == cudaSuccess, "shared attribute: ", cudaGetErrorString(err));
  });
}

void kernel(const torch::Tensor& probs, const torch::Tensor& top_p,
            const torch::Tensor& out) {
  TORCH_CHECK(probs.is_cuda() && top_p.is_cuda() && out.is_cuda(), "CUDA tensors required");
  TORCH_CHECK(probs.scalar_type() == torch::kFloat32 && top_p.scalar_type() == torch::kFloat32 &&
                  out.scalar_type() == torch::kFloat32,
              "float32 required");
  TORCH_CHECK(probs.dim() == 2 && out.dim() == 2, "rank 2 inputs and outputs");
  TORCH_CHECK(top_p.dim() == 1, "rank 1 top_p");
  const int64_t rows = probs.size(0);
  const int64_t cols = probs.size(1);
  TORCH_CHECK(out.size(0) == rows && out.size(1) == cols, "output shape mismatch");
  TORCH_CHECK(top_p.size(0) == rows, "top_p shape mismatch");
  TORCH_CHECK(probs.stride(1) == 1 && out.stride(1) == 1 && top_p.stride(0) == 1,
              "unit inner stride required");
  TORCH_CHECK(probs.device() == out.device() && probs.device() == top_p.device(),
              "device mismatch");
  if (rows == 0 || cols == 0) return;

  c10::cuda::CUDAGuard guard(probs.device());
  configure_once();
  const cudaStream_t stream = c10::cuda::getCurrentCUDAStream(probs.get_device()).stream();
  top_p_renorm<<<uint32_t(rows), kThreads, kSharedBytes, stream>>>(
      probs.data_ptr<float>(), probs.stride(0), top_p.data_ptr<float>(),
      out.data_ptr<float>(), out.stride(0), int(cols));
  const cudaError_t err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "top_p launch: ", cudaGetErrorString(err));
}

}  // namespace

PYBIND11_MODULE(TORCH_EXTENSION_NAME, module) {
  module.def("kernel", &kernel);
}

